import sys

def solve():
    MOD = 998244353
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    idx = 0
    N = int(data[idx]); idx += 1
    Q = int(data[idx]); idx += 1
    A = [0, 0]
    for i in range(N - 1):
        A.append(int(data[idx])); idx += 1
    # A[2..N]

    max_n = N + 5
    fact = [1] * max_n
    for i in range(1, max_n):
        fact[i] = fact[i-1] * i % MOD

    inv_int = [0] * max_n
    inv_int[1] = 1
    for i in range(2, max_n):
        inv_int[i] = (MOD - MOD // i) * inv_int[MOD % i] % MOD

    # P1[i] = sum_{j=2}^{i} A_j * 2(j-1)/(j(j+1))
    # P2[i] = sum_{j=2}^{i} A_j / j
    P1 = [0] * (N + 2)
    P2 = [0] * (N + 2)
    for j in range(2, N + 1):
        coef1 = 2 * (j - 1) % MOD * inv_int[j] % MOD * inv_int[j + 1] % MOD
        coef2 = inv_int[j]
        P1[j] = (P1[j-1] + A[j] * coef1) % MOD
        P2[j] = (P2[j-1] + A[j] * coef2) % MOD

    factN1 = fact[N - 1]

    out = []
    for _ in range(Q):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        if u == 1:
            # f_i = 1/i for 2 <= i < v, f_v = 1
            S = (P2[v-1] + A[v]) % MOD
        else:
            # f_i = 2(i-1)/(i(i+1)) for 2<=i<u, f_u=(u-1)/u, f_i=1/i for u<i<v, f_v=1
            term_u = A[u] * (u - 1) % MOD * inv_int[u] % MOD
            S = (P1[u-1] + term_u + (P2[v-1] - P2[u]) + A[v]) % MOD
        ans = S * factN1 % MOD
        out.append(ans)

    sys.stdout.write('\n'.join(map(str, out)) + '\n')

